import test from 'node:test';import assert from 'node:assert/strict';import{mkdtemp,rm}from'node:fs/promises';import{tmpdir}from'node:os';import{join}from'node:path';import{apply}from'../../lib/dsh.mjs';
test('ordinary plugin provides source discovery and owns its storage/routes/disposal; no client hook',async t=>{const root=await mkdtemp(join(tmpdir(),'hm-core-source-adapter-'));t.after(()=>rm(root,{recursive:true,force:true}));const provided=new Map(),routes=[],effects=[],domains=[],closed=[];const ctx={storageDomain:{async open(spec){domains.push(spec.name);let state=structuredClone(spec.global.initial);return {global:{get:()=>state,set:async v=>{state=structuredClone(v)}},close:async()=>{closed.push(spec.name)}}}},connection:{fetch:{register(r){routes.push(r);return()=>{routes.splice(routes.indexOf(r),1)}}},requestRejection:r=>r.headers.has('x-fixture')?undefined:401},loader:{entries:()=>[],options:{}},provide(n,v){provided.set(n,v);return()=>provided.delete(n)},on(){return()=>{}},effect(f){effects.push(f())}};await apply(ctx,{serverOrigin:null,websiteOrigin:null,sharedIdentityDir:root,allowSystemBrowser:false,suitePackageRegistries:[]});t.after(async()=>{if(effects.length)await effects[0]()});assert(provided.has('hanameshSuiteSource'),'Core must publicly own source discovery');assert.equal(provided.get('hanameshSuiteSource').getState().status,'disabled');assert.deepEqual(domains,['hanamesh_core','hanamesh_core_health','hanamesh_core_suite_source']);const route=routes.find(r=>r.path==='/api/hanamesh/core/suite-source');assert.deepEqual(route.methods,['GET','POST']);const response=await route.fetch(new Request('http://127.0.0.1/api/hanamesh/core/suite-source',{headers:{'x-fixture':'1'}}));assert.equal(response.status,200);assert.equal((await response.json()).registry,null);await effects.pop()();assert.equal(provided.size,0);assert.equal(routes.length,0);assert.deepEqual(closed.sort(),domains.sort())});

import {sourceArchives} from './source-archives.mjs';
async function readyFixture(t,failAt){
 const root=await mkdtemp(join(tmpdir(),'hm-core-ready-adapter-'));t.after(()=>rm(root,{recursive:true,force:true}));
 const options=await sourceArchives(t),provided=new Map(),routes=[],closed=[],effects=[];let ownedURL,effectDisposed=false;
 t.after(async()=>{if(effects.length)await effects[0]()});
 const ctx={storageDomain:{async open(spec){let state=structuredClone(spec.global.initial);return {global:{get:()=>state,set:async v=>{state=structuredClone(v)}},close:async()=>{closed.push(spec.name);if(failAt==='source-close'&&spec.name==='hanamesh_core_suite_source')throw Error('SOURCE_STORE_CLOSE_FAIL')}}}},connection:{fetch:{register(r){routes.push(r);return()=>{routes.splice(routes.indexOf(r),1)}}},requestRejection:()=>undefined},loader:{entries:()=>[],options:{}},provide(n,v){provided.set(n,v);if(n==='hanameshSuiteSource')ownedURL=v.getState().registry;return()=>provided.delete(n)},on(){if(failAt==='register')throw Error('SOURCE_ROUTE_REGISTER_FAIL');return()=>{}},effect(f){const close=f();effects.push(async()=>{if(effectDisposed)return;effectDisposed=true;return close()})}};
 return {ctx,config:{serverOrigin:null,websiteOrigin:null,sharedIdentityDir:root,allowSystemBrowser:false,suitePackageSource:options,suitePackageRegistries:[]},provided,routes,closed,effects,get ownedURL(){return ownedURL}};
}
test('ready source is released when activation fails after multiple route registrations',async t=>{const f=await readyFixture(t,'register');await assert.rejects(apply(f.ctx,f.config),e=>e.message==='SOURCE_ROUTE_REGISTER_FAIL');assert(f.ownedURL);await assert.rejects(fetch(f.ownedURL));assert.equal(f.provided.size,0);assert.equal(f.routes.length,0);assert.deepEqual(f.closed.sort(),['hanamesh_core','hanamesh_core_health','hanamesh_core_suite_source'].sort());assert.equal(f.effects.length,0)});
test('source storage close failure is named and does not leave routes, providers, leases or other domains active',async t=>{const f=await readyFixture(t,'source-close');await apply(f.ctx,f.config);const service=f.provided.get('hanameshSuiteSource');assert.equal(service.getState().status,'ready');await assert.rejects(f.effects[0](),e=>e.code==='CORE_PLUGIN_CLEANUP_FAILED'&&e.errors.some(cause=>cause.code==='CORE_SUITE_SOURCE_STORAGE_UNAVAILABLE'));await assert.rejects(fetch(f.ownedURL));assert.equal(service.getState().status,'disposed');assert.equal(f.provided.size,0);assert.equal(f.routes.length,0);assert.deepEqual(f.closed.sort(),['hanamesh_core','hanamesh_core_health','hanamesh_core_suite_source'].sort())});
test('Core declaration only admits the live owned source without rewriting configured registry lists',async t=>{const f=await readyFixture(t);await apply(f.ctx,f.config);t.after(()=>f.effects[0]());const source=f.provided.get('hanameshSuiteSource'),core=f.provided.get('hanameshCore');const declaration=await core.getSuiteDeclaration({registry:source.getState().registry});assert.equal(declaration.registry,f.ownedURL);for(const name of ['hanamesh-core','hanamesh-usage','@hanamesh/dsh-app-host'])assert.match(declaration.metadataDigests['registry:'+name],/^[a-f0-9]{64}$/);assert(!declaration.blocked.some(row=>row.code==='CORE_SUITE_SOURCE_UNSUPPORTED'),JSON.stringify(declaration.blocked));assert.deepEqual(f.config.suitePackageRegistries,[]);const foreign=await core.getSuiteDeclaration({registry:'http://127.0.0.1:12345/'});assert(foreign.blocked.some(row=>row.code==='CORE_SUITE_SOURCE_UNSUPPORTED'))});

test('routes exist before storage activation and wait for the exact activation rather than returning 404',async t=>{const f=await readyFixture(t);let release;const paused=new Promise(resolve=>{release=resolve}),original=f.ctx.storageDomain.open;let entered;const waiting=new Promise(resolve=>{entered=resolve});f.ctx.storageDomain.open=async function(spec){if(spec.name==='hanamesh_core'){entered();await paused}return original.call(this,spec)};const running=apply(f.ctx,f.config);t.after(async()=>{release();await running});await waiting;const state=f.routes.find(r=>r.path==='/api/hanamesh/core/state');assert(state,'Core must register before asynchronous storage/source activation');let done=false;const response=state.fetch(new Request('http://dsh.invalid/api/hanamesh/core/state')).then(r=>{done=true;return r});await Promise.resolve();assert.equal(done,false);release();await running;assert.equal((await response).status,200);assert.equal((await(await response).json()).serverOrigin,null)});
